'use client'

import Image from 'next/image'
import { useEffect, useRef, useState } from 'react'
import { animate, motion, useInView, useReducedMotion } from 'framer-motion'
import { cn } from '@/lib/utils'

export type CredibilityStat = { value: number; suffix?: string; label: string }
export type CredibilityReason = { title: string; description: string }

export type CredibilitySectionProps = {
  title: string
  description?: string
  stats?: CredibilityStat[]
  reasons: CredibilityReason[]
  image?: { src: string; alt: string }
  caption?: string
  className?: string
}

function CountUp({ value, suffix = '' }: { value: number; suffix?: string }) {
  const ref = useRef<HTMLSpanElement>(null)
  const inView = useInView(ref, { once: true })
  const reduceMotion = useReducedMotion()
  const [display, setDisplay] = useState(reduceMotion ? value : 0)

  useEffect(() => {
    if (!inView || reduceMotion) return
    const controls = animate(0, value, {
      duration: 1.6,
      ease: 'easeOut',
      onUpdate: (latest) => setDisplay(Math.round(latest)),
    })
    return () => controls.stop()
  }, [inView, reduceMotion, value])

  return (
    <span ref={ref} className="tabular-nums">
      {display}
      {suffix}
    </span>
  )
}

export function CredibilitySection({
  title,
  description,
  stats = [],
  reasons,
  image,
  caption,
  className,
}: CredibilitySectionProps) {
  const reduceMotion = useReducedMotion()

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="max-w-3xl">
          <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{title}</h2>
          {description ? (
            <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
        </div>

        {stats.length ? (
          <dl className="mt-10 grid gap-6 border-y py-8 sm:grid-cols-3">
            {stats.map((stat) => (
              <div key={stat.label}>
                <dt className="sr-only">{stat.label}</dt>
                <dd className="text-5xl font-bold text-primary">
                  <CountUp value={stat.value} suffix={stat.suffix} />
                </dd>
                <dd className="mt-2 text-sm font-medium text-muted-foreground">{stat.label}</dd>
              </div>
            ))}
          </dl>
        ) : null}

        <div className={cn('mt-12 grid gap-10', image && 'lg:grid-cols-[0.8fr_1.2fr]')}>
          {image ? (
            <figure className="lg:sticky lg:top-24 lg:self-start">
              <div className="relative aspect-[4/5] overflow-hidden rounded-3xl bg-muted">
                <Image
                  src={image.src}
                  alt={image.alt}
                  fill
                  className="object-cover"
                  sizes="(min-width: 1024px) 35vw, 100vw"
                />
              </div>
              {caption ? (
                <figcaption className="mt-3 text-sm text-muted-foreground">{caption}</figcaption>
              ) : null}
            </figure>
          ) : null}
          <ol className="grid gap-px overflow-hidden rounded-3xl border bg-border sm:grid-cols-2">
            {reasons.map((reason, index) => (
              <motion.li
                key={reason.title}
                initial={reduceMotion ? false : { opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.45, delay: (index % 2) * 0.1 }}
                className="group bg-background p-6 transition hover:bg-primary/5"
              >
                <span className="font-mono text-sm font-bold text-primary transition group-hover:tracking-widest">
                  {String(index + 1).padStart(2, '0')}
                </span>
                <h3 className="mt-3 text-lg font-semibold">{reason.title}</h3>
                <p className="mt-2 text-sm leading-6 text-muted-foreground">{reason.description}</p>
              </motion.li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'

import { AccentButton } from '@/components/library/primitives/AccentButton'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type IconFeatureCardItem = {
  title: string
  description: string
  icon?: ReactNode
  action?: { label: string; href: string }
}

export type IconFeatureCardsProps = {
  title: string
  items: readonly IconFeatureCardItem[]
  eyebrow?: string
  description?: string
  columns?: 2 | 3 | 4
  tone?: AccentTone
  className?: string
}

const columnClasses = {
  2: 'sm:grid-cols-2',
  3: 'sm:grid-cols-2 lg:grid-cols-3',
  4: 'sm:grid-cols-2 lg:grid-cols-4',
}

const cardStyles: Record<AccentTone, { card: string; icon: string }> = {
  glow: {
    card: 'rounded-md bg-[#221d2f]',
    icon: 'rounded-xl bg-[#121212] text-[#ffb0eb]',
  },
  industrial: {
    card: 'border border-slate-200 bg-white',
    icon: 'bg-slate-100 text-amber-600',
  },
  'industrial-dark': {
    card: 'border border-white/10 bg-slate-900',
    icon: 'bg-slate-950 text-amber-500',
  },
}

/** Cards de diferenciais com ícone em destaque, texto e ação individual. */
export function IconFeatureCards({
  title,
  items,
  eyebrow,
  description,
  columns = 3,
  tone = 'glow',
  className,
}: IconFeatureCardsProps) {
  const t = getAccentTone(tone)
  const styles = cardStyles[tone]

  return (
    <section className={cn('w-full py-12 lg:py-16', t.section, className)}>
      <div className="container">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          className="mb-8"
        />
        <div className={cn('grid grid-cols-1 gap-6', columnClasses[columns])}>
          {items.map((item) => (
            <article
              key={item.title}
              className={cn(
                'relative flex min-h-[240px] flex-col items-start gap-3 overflow-hidden p-6',
                styles.card,
              )}
            >
              {item.icon ? (
                <div
                  className={cn(
                    'p-4 [&_img]:h-12 [&_img]:w-12 [&_svg]:h-8 [&_svg]:w-8',
                    styles.icon,
                  )}
                  aria-hidden
                >
                  {item.icon}
                </div>
              ) : null}
              <h3
                className={cn(
                  'text-[clamp(1.25rem,2vw,1.5rem)] font-semibold',
                  tone !== 'glow' && 'uppercase tracking-wide',
                  t.strong,
                )}
              >
                {item.title}
              </h3>
              <p className={cn('m-0', t.body)}>{item.description}</p>
              {item.action ? (
                <AccentButton href={item.action.href} tone={tone} className="mt-auto">
                  {item.action.label}
                </AccentButton>
              ) : null}
              <span className={cn('absolute inset-x-0 bottom-0 h-px', t.line)} aria-hidden />
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

import { Check } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ProcessStepsProps = {
  title: string
  description?: string
  steps: Array<{ title: string; description: string }>
  className?: string
}

export function ProcessSteps({ title, description, steps, className }: ProcessStepsProps) {
  return (
    <section
      className={cn('bg-muted/30 py-16 md:py-24', className)}
      aria-labelledby="process-title"
    >
      <div className="container">
        <div className="max-w-2xl">
          <h2 id="process-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
          {description ? <p className="mt-4 text-lg text-muted-foreground">{description}</p> : null}
        </div>
        <ol className="mt-10 grid gap-5 md:grid-cols-2 lg:grid-cols-4">
          {steps.map((step, index) => (
            <li
              key={step.title}
              className="relative rounded-2xl border bg-background p-6 shadow-sm"
            >
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-primary font-bold text-primary-foreground">
                {index + 1}
              </span>
              <h3 className="mt-5 text-lg font-semibold">{step.title}</h3>
              <p className="mt-2 text-sm leading-6 text-muted-foreground">{step.description}</p>
              {index === steps.length - 1 ? (
                <Check className="absolute right-5 top-5 h-5 w-5 text-primary" aria-hidden="true" />
              ) : null}
            </li>
          ))}
        </ol>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'

import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type CTASplitPanelProps = {
  title: string
  description?: string
  eyebrow?: string
  actions?: ReactNode
  tone?: AccentTone
  className?: string
}

/** Painel com borda: texto à esquerda e ações à direita, empilhado no mobile. */
export function CTASplitPanel({
  title,
  description,
  eyebrow,
  actions,
  tone = 'industrial',
  className,
}: CTASplitPanelProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'

  return (
    <section className={cn('w-full py-12 lg:py-16', t.section, className)}>
      <div className="container">
        <div
          className={cn(
            'relative flex flex-col gap-8 overflow-hidden border p-8 sm:p-10 lg:flex-row lg:items-center lg:justify-between lg:p-12',
            t.panel,
            t.border,
            isGlow && 'rounded-2xl',
          )}
        >
          <span className={cn('absolute inset-y-0 left-0 w-1', t.line)} aria-hidden />
          <div className="max-w-2xl">
            {eyebrow ? (
              <span
                className={cn(
                  'mb-3 inline-block text-xs font-semibold uppercase tracking-[0.2em]',
                  t.accent,
                )}
              >
                {eyebrow}
              </span>
            ) : null}
            <h2 className={cn('text-2xl md:text-3xl', t.heading)}>{title}</h2>
            {description ? (
              <p className={cn('mt-4 text-base leading-relaxed', t.body)}>{description}</p>
            ) : null}
          </div>
          {actions ? <div className="flex shrink-0 flex-wrap gap-3">{actions}</div> : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId } from 'react'
import { HelpCircle } from 'lucide-react'

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion'
import { cn } from '@/lib/utils'

export type FAQCenteredProps = {
  eyebrow?: string
  title: string
  description?: string
  items: Array<{
    question: string
    answer: React.ReactNode
  }>
  className?: string
}

export function FAQCentered({
  eyebrow = 'Central de ajuda',
  title,
  description,
  items,
  className,
}: FAQCenteredProps) {
  const titleId = useId()

  return (
    <section className={cn('py-16 md:py-24', className)} aria-labelledby={titleId}>
      <div className="container">
        <header className="mx-auto mb-10 max-w-2xl text-center">
          <span className="mb-5 inline-flex items-center gap-2 rounded-full border bg-background px-3 py-1 text-xs font-semibold uppercase tracking-wider text-muted-foreground shadow-sm">
            <HelpCircle className="size-3.5 text-primary" aria-hidden="true" />
            {eyebrow}
          </span>
          <h2 id={titleId} className="text-balance text-3xl font-bold tracking-tight md:text-5xl">
            {title}
          </h2>
          {description ? (
            <p className="mx-auto mt-4 max-w-xl text-balance text-muted-foreground">
              {description}
            </p>
          ) : null}
        </header>

        <Accordion type="single" collapsible className="mx-auto max-w-3xl space-y-3">
          {items.map((item, index) => (
            <AccordionItem
              key={item.question}
              value={`faq-centered-${index}`}
              className="rounded-2xl border bg-card px-5 shadow-sm data-[state=open]:border-primary/30 data-[state=open]:shadow-md"
            >
              <AccordionTrigger className="py-5 text-left text-base font-semibold hover:no-underline">
                {item.question}
              </AccordionTrigger>
              <AccordionContent className="pb-5 pr-8 leading-7 text-muted-foreground">
                {item.answer}
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      </div>
    </section>
  )
}

import Image from 'next/image'

import { cn } from '@/lib/utils'

export type AccentTestimonial = {
  name: string
  content: string
  role?: string
  avatar?: string
  rating?: number
}

export function TestimonialAvatar({
  name,
  src,
  className,
}: {
  name: string
  src?: string
  className?: string
}) {
  const initials = name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('')

  return (
    <span
      className={cn(
        'relative flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden text-sm font-semibold',
        className,
      )}
    >
      {src ? (
        <Image src={src} alt={name} fill sizes="48px" className="object-cover" />
      ) : (
        <span aria-hidden>{initials}</span>
      )}
    </span>
  )
}

'use client'

import { useState } from 'react'
import { ChevronLeft, ChevronRight, Quote, Star } from 'lucide-react'
import type { Swiper as SwiperInstance } from 'swiper'
import { A11y, Autoplay, Keyboard } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import { TestimonialAvatar, type AccentTestimonial } from './TestimonialAvatar'

import 'swiper/css'

export type TestimonialsQuoteSliderProps = {
  title: string
  testimonials: readonly AccentTestimonial[]
  eyebrow?: string
  description?: string
  autoplayDelay?: number
  tone?: AccentTone
  className?: string
}

/** Slider de depoimentos com aspas, avaliação em estrelas, paginação e setas. */
export function TestimonialsQuoteSlider({
  title,
  testimonials,
  eyebrow,
  description,
  autoplayDelay = 5500,
  tone = 'industrial',
  className,
}: TestimonialsQuoteSliderProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const reduced = useReducedMotion()
  const [swiper, setSwiper] = useState<SwiperInstance | null>(null)
  const [activeIndex, setActiveIndex] = useState(0)
  const star = isGlow ? 'fill-[#ffb0eb] text-[#ffb0eb]' : 'fill-amber-500 text-amber-500'

  return (
    <section className={cn('relative overflow-hidden', t.section, className)}>
      <div className="container py-14 lg:py-16">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          layout="split"
          className="mb-10 lg:mb-12"
        />

        <Swiper
          modules={[A11y, Autoplay, Keyboard]}
          spaceBetween={0}
          slidesPerView={1}
          loop={testimonials.length > 3}
          keyboard={{ enabled: true }}
          autoplay={reduced ? false : { delay: autoplayDelay, disableOnInteraction: false }}
          breakpoints={{ 768: { slidesPerView: 2 }, 1024: { slidesPerView: 3 } }}
          onSwiper={setSwiper}
          onSlideChange={(instance) => setActiveIndex(instance.realIndex)}
          className={cn('border', t.border, isGlow && 'rounded-2xl')}
        >
          {testimonials.map((testimonial) => (
            <SwiperSlide key={testimonial.name + testimonial.content} className="!h-auto">
              <article
                className={cn(
                  'flex h-full min-h-[22rem] flex-col justify-between border-l p-7 sm:p-8',
                  t.panel,
                  t.border,
                )}
              >
                <div>
                  <div className="mb-6 flex items-start justify-between gap-4">
                    <Quote className={cn('h-8 w-8', t.accent)} strokeWidth={1.5} aria-hidden />
                    {testimonial.rating ? (
                      <div
                        className="flex items-center gap-0.5"
                        role="img"
                        aria-label={`${testimonial.rating} de 5 estrelas`}
                      >
                        {Array.from({ length: testimonial.rating }, (_, index) => (
                          <Star key={index} className={cn('h-3.5 w-3.5', star)} aria-hidden />
                        ))}
                      </div>
                    ) : null}
                  </div>
                  <blockquote className={cn('text-base leading-relaxed', t.body)}>
                    &ldquo;{testimonial.content}&rdquo;
                  </blockquote>
                </div>
                <div className={cn('mt-8 flex items-center gap-4 border-t pt-6', t.border)}>
                  <TestimonialAvatar
                    name={testimonial.name}
                    src={testimonial.avatar}
                    className={cn('border', t.border, t.accent, isGlow && 'rounded-full')}
                  />
                  <div>
                    <p
                      className={cn(
                        'text-sm font-semibold tracking-wide',
                        !isGlow && 'uppercase',
                        t.strong,
                      )}
                    >
                      {testimonial.name}
                    </p>
                    {testimonial.role ? (
                      <p className={cn('mt-0.5 text-xs uppercase tracking-[0.16em]', t.muted)}>
                        {testimonial.role}
                      </p>
                    ) : null}
                  </div>
                </div>
              </article>
            </SwiperSlide>
          ))}
        </Swiper>

        <div className="mt-8 flex items-center justify-between gap-4">
          <div className="flex items-center gap-1.5">
            {testimonials.map((testimonial, index) => (
              <button
                key={testimonial.name + index}
                type="button"
                onClick={() => swiper?.slideToLoop(index)}
                className={cn('py-2', t.focus)}
                aria-label={`Ir para o depoimento ${index + 1}`}
                aria-current={index === activeIndex ? 'true' : undefined}
              >
                <span
                  className={cn(
                    'block h-0.5 transition-all duration-300',
                    index === activeIndex
                      ? cn('w-10', t.line)
                      : cn(
                          'w-7',
                          isGlow
                            ? 'bg-[#493849]'
                            : tone === 'industrial'
                              ? 'bg-slate-300'
                              : 'bg-white/15',
                        ),
                  )}
                />
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => swiper?.slidePrev()}
              className={cn(
                'flex h-10 w-10 items-center justify-center transition-colors',
                t.iconButton,
                t.focus,
              )}
              aria-label="Depoimento anterior"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              type="button"
              onClick={() => swiper?.slideNext()}
              className={cn(
                'flex h-10 w-10 items-center justify-center transition-colors',
                t.iconButton,
                t.focus,
              )}
              aria-label="Próximo depoimento"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          </div>
        </div>
      </div>
    </section>
  )
}

'use client'

import { useState, type FormEvent } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { cn } from '@/lib/utils'

export type ContactFormData = {
  name: string
  email: string
  phone: string
  subject: string
  message: string
}
export type ContactFormProps = {
  title?: string
  description?: string
  endpoint?: string
  submitLabel?: string
  onSubmit?: (data: ContactFormData) => Promise<void> | void
  onSuccess?: (data: ContactFormData) => void
  className?: string
}

export function ContactForm({
  title = 'Fale conosco',
  description,
  endpoint = '/api/contato',
  submitLabel = 'Enviar mensagem',
  onSubmit,
  onSuccess,
  className,
}: ContactFormProps) {
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle')

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = event.currentTarget
    const formData = new FormData(form)
    const data: ContactFormData = {
      name: String(formData.get('name') ?? ''),
      email: String(formData.get('email') ?? ''),
      phone: String(formData.get('phone') ?? ''),
      subject: String(formData.get('subject') ?? ''),
      message: String(formData.get('message') ?? ''),
    }
    setStatus('submitting')
    try {
      if (onSubmit) await onSubmit(data)
      else {
        const response = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data),
        })
        if (!response.ok) throw new Error('Não foi possível enviar a mensagem.')
      }
      setStatus('success')
      form.reset()
      onSuccess?.(data)
    } catch {
      setStatus('error')
    }
  }

  return (
    <section
      className={cn('rounded-2xl border bg-card p-6 shadow-sm md:p-8', className)}
      aria-labelledby="contact-form-title"
    >
      <h2 id="contact-form-title" className="text-2xl font-bold">
        {title}
      </h2>
      {description ? <p className="mt-2 text-muted-foreground">{description}</p> : null}
      <form className="mt-7 grid gap-5" onSubmit={handleSubmit}>
        <div className="grid gap-5 sm:grid-cols-2">
          <label className="grid gap-2 text-sm font-medium">
            Nome
            <Input name="name" autoComplete="name" required />
          </label>
          <label className="grid gap-2 text-sm font-medium">
            E-mail
            <Input name="email" type="email" autoComplete="email" required />
          </label>
          <label className="grid gap-2 text-sm font-medium">
            Telefone
            <Input name="phone" type="tel" autoComplete="tel" />
          </label>
          <label className="grid gap-2 text-sm font-medium">
            Assunto
            <Input name="subject" required />
          </label>
        </div>
        <label className="grid gap-2 text-sm font-medium">
          Mensagem
          <Textarea name="message" rows={5} required />
        </label>
        <div className="flex flex-wrap items-center gap-4">
          <Button type="submit" disabled={status === 'submitting'}>
            {status === 'submitting' ? 'Enviando…' : submitLabel}
          </Button>
          <div aria-live="polite" className="text-sm">
            {status === 'success' ? (
              <p className="text-emerald-600">Mensagem enviada com sucesso.</p>
            ) : null}
            {status === 'error' ? (
              <p className="text-destructive">Não foi possível enviar. Tente novamente.</p>
            ) : null}
          </div>
        </div>
      </form>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroSplitProps = {
  title: string
  description?: string
  image: { src: string; alt: string }
  eyebrow?: string
  action?: { label: string; href: string }
  imagePosition?: 'left' | 'right'
  className?: string
}

export function HeroSplit({
  title,
  description,
  image,
  eyebrow,
  action,
  imagePosition = 'right',
  className,
}: HeroSplitProps) {
  return (
    <section
      className={cn('overflow-hidden border-b bg-background', className)}
